begin;
set local lock_timeout='1s';
set local statement_timeout='5s';

-- Positive, server-owned provenance. Legacy audit history is deliberately not
-- relabelled: it can contain invoice fields without a reliable turn marker.
create table public.whatsapp_provider_memory (
  id bigint generated always as identity primary key,
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  owner_id uuid references auth.users(id) on delete cascade,
  customer_id uuid,
  phone text not null,
  audience text not null check (audience in ('owner','customer')),
  source_message_id text not null,
  role text not null check (role in ('user','assistant')),
  content text not null check (length(content) between 1 and 4000),
  provenance text not null check (provenance='ordinary_chat_v1'),
  created_at timestamptz not null default now(),
  foreign key(workspace_id,customer_id) references public.customers(workspace_id,id) on delete cascade,
  check ((audience='owner' and owner_id is not null and customer_id is null)
    or (audience='customer' and customer_id is not null and owner_id is null)),
  unique(workspace_id,phone,audience,source_message_id,role)
);
create index whatsapp_provider_memory_scope on public.whatsapp_provider_memory(workspace_id,phone,audience,id desc);
alter table public.whatsapp_provider_memory enable row level security;
revoke all on public.whatsapp_provider_memory from public,anon,authenticated,service_role;
grant select,insert,delete on public.whatsapp_provider_memory to service_role;
revoke all on sequence public.whatsapp_provider_memory_id_seq from public,anon,authenticated,service_role;
grant usage,select on sequence public.whatsapp_provider_memory_id_seq to service_role;

-- Retain local terms even when a review is replaced/cancelled or history is
-- pruned. This prevents later quotations from laundering fields into chat.
create table public.whatsapp_private_invoice_terms (
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  term_hash text not null,
  term text not null check(length(term) between 1 and 4000),
  primary key(workspace_id,term_hash)
);
alter table public.whatsapp_private_invoice_terms enable row level security;
revoke all on public.whatsapp_private_invoice_terms from public,anon,authenticated,service_role;
grant select,insert on public.whatsapp_private_invoice_terms to service_role;

-- Completed canonical inputs, keyed by raw input, semantic role, workspace and
-- generated canonicalizer revision. No invoice values are stored here. A row
-- appears only AFTER all aliases commit; it is never a readiness/privacy wall.
create table app.private_invoice_canonical_inputs (
 workspace_id uuid not null references public.workspaces(id) on delete cascade,
 canonicalizer_revision bytea not null,
 input_kind text not null check(input_kind in ('generic','monetary','party','number','evidence','origin')),
 input_hash bytea not null,
 primary key(workspace_id,canonicalizer_revision,input_kind,input_hash)
);
alter table app.private_invoice_canonical_inputs enable row level security;
revoke all on app.private_invoice_canonical_inputs from public,anon,authenticated,service_role;

-- Privileged maintenance has its own generation, independent of the pure
-- canonicalizer revision. A racing completion keeps its entry-time generation.
create table app.private_invoice_capture_epochs (
 workspace_id uuid primary key references public.workspaces(id) on delete cascade,
 generation bigint not null check(generation>0)
);
create table app.private_invoice_capture_state (
 singleton boolean primary key check(singleton), generation bigint not null check(generation>=0)
);
insert into app.private_invoice_capture_state values(true,0);
alter table app.private_invoice_capture_epochs enable row level security;
alter table app.private_invoice_capture_state enable row level security;
revoke all on app.private_invoice_capture_epochs,app.private_invoice_capture_state from public,anon,authenticated,service_role;

-- AFTER DELETE remains nonblocking with respect to a completion paused before
-- insertion. Its generation makes that later stale marker unusable on replay.
create function app.invalidate_private_canonical_inputs() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 insert into app.private_invoice_capture_epochs as e(workspace_id,generation)
 select distinct t.workspace_id,1 from removed_private_terms t
 where exists(select 1 from public.workspaces w where w.id=t.workspace_id)
 on conflict(workspace_id) do update set generation=e.generation+1;
 delete from app.private_invoice_canonical_inputs where workspace_id in
  (select workspace_id from removed_private_terms);
 return null;
end $$;
revoke all on function app.invalidate_private_canonical_inputs() from public,anon,authenticated,service_role;
create trigger invalidate_private_canonical_inputs after delete on public.whatsapp_private_invoice_terms
 referencing old table as removed_private_terms for each statement execute function app.invalidate_private_canonical_inputs();

-- TRUNCATE has no transition rows. Advance one global generation and clear
-- completed inputs in the same maintenance transaction. No API privilege added.
create function app.truncate_private_canonical_inputs() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 update app.private_invoice_capture_state set generation=generation+1 where singleton;
 truncate app.private_invoice_canonical_inputs;
 return null;
end $$;
revoke all on function app.truncate_private_canonical_inputs() from public,anon,authenticated,service_role;
create trigger truncate_private_canonical_inputs after truncate on public.whatsapp_private_invoice_terms
 for each statement execute function app.truncate_private_canonical_inputs();

-- Service-only resumable cursors. Readiness is true only after every source
-- has committed its final batch; provider memory fails closed until then.
create table public.whatsapp_private_invoice_backfill (
 source text primary key check(source in ('invoices','reviews','owner_quotes','customer_quotes')),
 last_key text, upper_key text, complete boolean not null default false,
 updated_at timestamptz not null default clock_timestamp()
);
alter table public.whatsapp_private_invoice_backfill enable row level security;
revoke all on public.whatsapp_private_invoice_backfill from public,anon,authenticated,service_role;
grant select on public.whatsapp_private_invoice_backfill to service_role;

-- Generated by scripts/generate-private-value-unicode.mjs; Unicode 17.0.
-- The identical code-point map is imported by JS: no locale-dependent lower().
create function app.private_invoice_normalize(p_term text) returns text
