declare fold jsonb; result text;
 working text:=translate(coalesce(p_term,''),'ABCDEFGHIJKLMNOPQRSTUVWXYZ'||chr(9)||chr(10)||chr(11)||chr(12)||chr(13),'abcdefghijklmnopqrstuvwxyz'||repeat(' ',5));
begin
