 -- One pass over ASCII runs / individual Unicode code points. Never re-fold
 -- replacement output, and preserve the map's exact expansion/deletion rules.
 select string_agg(case when octet_length(piece[1])=length(piece[1]) then piece[1] else coalesce(fold->>piece[1],piece[1]) end,'' order by ordinal)
 into result from regexp_matches(working collate "C",U&'[\0001-\007f]+|[^\0001-\007f]','g') with ordinality as chunks(piece,ordinal);
 return btrim(regexp_replace(coalesce(result,''),' +',' ','g'));
end $$;
