-- One scalar normalization primitive owns currency, quote and separator rules.
create function app.private_invoice_number_scalar(p_term text) returns text
language plpgsql immutable set search_path='' as $$
declare term text; prior text;unit_pattern text:='(?:inr|usd|eur|gbp|aed|sgd|aud|cad|chf|rs\.?|rupees?|dollars?|euros?|pounds?)';
begin
  -- Already-canonical ASCII numeric runs need no Unicode or wrapper passes.
  if p_term ~ '^[0-9]+([.,'' ][0-9]+)*([kmb])?$' then return p_term;end if;
  term:=app.private_invoice_normalize(p_term);
  term:=regexp_replace(term,'/[-−]$','');
  term:=regexp_replace(term,U&'^[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]+|[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]+$','','g');
  term:=regexp_replace(term,'^\((.*)\)$','\1');
  term:=regexp_replace(term,U&'[\0022\0027\00ab\00bb\2018-\201f\2039-\203a\2e42\300c-\300f\301d-\301f\fe41-\fe44\ff02\ff07\ff62-\ff63\02bc]',chr(39),'g');
  loop
    prior:=term;
    term:=btrim(regexp_replace(term,'^(?:[+−-]|'||U&'[\0024\00a2-\00a5\058f\060b\07fe-\07ff\09f2-\09f3\09fb\0af1\0bf9\0e3f\17db\20a0-\20c1\a838\fdfc\fe69\ff04\ffe0-\ffe1\ffe5-\ffe6\+011fdd-\+011fe0\+01e2ff\+01ecb0]'||'|'||unit_pattern||') *| *(?:'||U&'[\0024\00a2-\00a5\058f\060b\07fe-\07ff\09f2-\09f3\09fb\0af1\0bf9\0e3f\17db\20a0-\20c1\a838\fdfc\fe69\ff04\ffe0-\ffe1\ffe5-\ffe6\+011fdd-\+011fe0\+01e2ff\+01ecb0]'||'|'||unit_pattern||')$','','g'));
    exit when term=prior;
  end loop;
  term:=regexp_replace(term,'[.,]+$','');
  return regexp_replace(term,' *([.,'']) *','\1','g');
end $$;
revoke all on function app.private_invoice_number_scalar(text) from public,anon,authenticated,service_role;

-- Grouping/decimal ambiguity and wrappers mirror numeric()/scalar() in JS.
create function app.private_invoice_number_aliases(p_term text) returns setof text
language plpgsql immutable set search_path='' as $$
declare term text:=app.private_invoice_number_scalar(p_term);whole text;fraction text;groups text[];valid boolean;i integer;multiplier numeric:=1;ratio text[];n numeric;d numeric;
begin
  if term ~ '[kmb]$' then
    multiplier:=case right(term,1) when 'k' then 1000 when 'm' then 1000000 else 1000000000 end;
    term:=btrim(left(term,length(term)-1));
  end if;
  if strpos(term,'/')>0 then
    ratio:=regexp_match(term,'^(?:([0-9]+) +)?([0-9]+) */ *([0-9]+)$');if ratio is null or ratio[3]::numeric=0 then return;end if;
    d:=ratio[3]::numeric;n:=(coalesce(ratio[1],'0')::numeric*d+ratio[2]::numeric)*power(10::numeric,20);
    n:=div(n,d);return next 'number:'||trim_scale((div(n,power(10::numeric,20))::text||'.'||lpad(trim_scale(mod(n,power(10::numeric,20)))::text,20,'0'))::numeric*multiplier)::text;return;
  end if;
  if term !~ '^[0-9]+([.,'' ][0-9]+)*$' then return; end if;
  for i in 1..2 loop
    fraction:='';whole:=term;
    if i=2 then
      if term !~ '[.,][0-9]+$' then continue; end if;
      fraction:=substring(term from '[.,]([0-9]+)$');whole:=regexp_replace(term,'[.,][0-9]+$','');
    end if;
    groups:=regexp_split_to_array(whole,'[.,'' ]');valid:=cardinality(groups)=1;
    if not valid and length(groups[1]) between 1 and 3 then
      valid:=not exists(select 1 from unnest(groups[2:cardinality(groups)]) g where length(g)<>3);
    end if;
    if not valid and length(groups[1]) between 1 and 2 and length(groups[cardinality(groups)])=3 then
      valid:=not exists(select 1 from unnest(groups[2:cardinality(groups)-1]) g where length(g)<>2);
    end if;
    if valid then return next 'number:'||trim_scale((array_to_string(groups,'')||case when fraction<>'' then '.'||fraction else '' end)::numeric*multiplier)::text;end if;
  end loop;
end $$;
revoke all on function app.private_invoice_number_aliases(text) from public,anon,authenticated,service_role;

-- Bounded rows retain a complete graph, identified and reconstructed as one run.
create function app.private_invoice_numeric_run_keys(p_run text) returns setof text
language plpgsql immutable set search_path='' as $$
declare id text;parts integer;i integer;
begin
 if length(p_run)<=3989 then return next 'number-run:'||p_run;return;end if;
 id:=encode(sha256(convert_to(p_run,'UTF8')),'hex');parts:=ceil(length(p_run)/3800.0)::integer;
 for i in 0..parts-1 loop return next 'number-run:'||jsonb_build_array(id,i,parts,substring(p_run from i*3800+1 for 3800))::text;end loop;
end $$;
revoke all on function app.private_invoice_numeric_run_keys(text) from public,anon,authenticated,service_role;

-- Same bounded candidate graph as numericList(). Atomic values preserve their
-- complete parse; enumeration only ADDS alternatives. No dropped whole values.
create function app.private_invoice_collection_rendering(p_term text) returns text
language plpgsql immutable set search_path='' as $$
declare result text:=app.private_invoice_normalize(p_term);m text[];value text;part text;offset_at integer:=1;rendered text:='';spoken boolean;
