 if exists(select 1 from unnest(r) w where w=any(array['choose','select','pick','compare','between','among','respectively','each','apiece'])) or exists(select 1 from unnest(l) w where w=any(array['choose','select','pick','compare','between','among','pair','couple','list','sequence','set','array','tuple','collection','group','range','both','either','neither','several','multiple','respectively','each','apiece'])) then return true;end if;
