        field:=app.private_invoice_tuple_participant(field,proper_names);
        return query select * from app.private_invoice_nominal_aliases(field,true,proper_names);
       end if;
      end if;amount_end:=b;
     end loop;
    end if;

   end if;
  end if;
 end if;
 marker:=regexp_match(working,'(?<![a-z0-9_])(?:notes?|currency)(?![a-z0-9_]) *(?:(?:is|was|to)(?![a-z0-9_]) *|[:=] *)');if marker is not null then field:=btrim(substring(working from regexp_instr(working,'(?<![a-z0-9_])(?:notes?|currency)(?![a-z0-9_]) *(?:(?:is|was|to)(?![a-z0-9_]) *|[:=] *)')+length(marker[1])));if field<>'' then return query select * from app.private_invoice_term_aliases(field);end if;end if;
end $$;
revoke all on function app.private_invoice_origin_projection(text,integer,jsonb) from public,anon,authenticated,service_role;
create function app.private_invoice_origin_segment_aliases(p_term text) returns setof text
language sql immutable set search_path='' as $$select * from app.private_invoice_origin_projection(p_term,null,null)$$;
revoke all on function app.private_invoice_origin_segment_aliases(text) from public,anon,authenticated,service_role;

-- One traversal supplies every independent event to the same projection.
create function app.private_invoice_origin_aliases(p_term text) returns setof text
language plpgsql immutable set search_path='' as $$
declare source text;prepared text;proper_names jsonb;cursor_at integer:=1;a integer;b integer;starts integer[]:=array[]::integer[];i integer;marker text[];head_span record;
begin
 if app.private_invoice_decode_json(p_term) is not null then return;end if;
 source:=app.private_invoice_normalize(regexp_replace(p_term,E'[\\r\\n]+',',','g'));source:=regexp_replace(source,'((?:the +)?(?:(?:[0-9]{1,2}(?:st|nd|rd|th)?|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth|twenty[ -]+first|twenty[ -]+second|twenty[ -]+third|twenty[ -]+fourth|twenty[ -]+fifth|twenty[ -]+sixth|twenty[ -]+seventh|twenty[ -]+eighth|twenty[ -]+ninth|thirtieth|thirty[ -]+first)|एक|दो|तीन|चार|पाँच|छह|सात|आठ|नौ|दस|ग्यारह|बारह|तेरह|चौदह|पंद्रह|सोलह|सत्रह|अठारह|उन्नीस|बीस|इक्कीस|बाईस|तेईस|चौबीस|पच्चीस|छब्बीस|सत्ताईस|अट्ठाईस|उनतीस|तीस|इकतीस)[ ./-]*(?:of +)?(?:(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)|जनवरी|फ़रवरी|फरवरी|मार्च|अप्रैल|मई|जून|जुलाई|अगस्त|सितंबर|सितम्बर|अक्टूबर|अक्तूबर|नवंबर|नवम्बर|दिसंबर|दिसम्बर)|(?:(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)|जनवरी|फ़रवरी|फरवरी|मार्च|अप्रैल|मई|जून|जुलाई|अगस्त|सितंबर|सितम्बर|अक्टूबर|अक्तूबर|नवंबर|नवम्बर|दिसंबर|दिसम्बर)[ ./-]*(?:the +)?(?:(?:[0-9]{1,2}(?:st|nd|rd|th)?|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth|twenty[ -]+first|twenty[ -]+second|twenty[ -]+third|twenty[ -]+fourth|twenty[ -]+fifth|twenty[ -]+sixth|twenty[ -]+seventh|twenty[ -]+eighth|twenty[ -]+ninth|thirtieth|thirty[ -]+first)|एक|दो|तीन|चार|पाँच|छह|सात|आठ|नौ|दस|ग्यारह|बारह|तेरह|चौदह|पंद्रह|सोलह|सत्रह|अठारह|उन्नीस|बीस|इक्कीस|बाईस|तेईस|चौबीस|पच्चीस|छब्बीस|सत्ताईस|अट्ठाईस|उनतीस|तीस|इकतीस))[ ./-]*,[ ./-]*([''’ʼ]?[0-9]{4}|[''’ʼ]?[0-9]{2})(?![0-9])',E'\\1 \\2','g');
 prepared:=app.private_invoice_normalize(regexp_replace(p_term,E'[\\r\\n]+',';','g'));prepared:=regexp_replace(prepared,'((?:the +)?(?:(?:[0-9]{1,2}(?:st|nd|rd|th)?|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth|twenty[ -]+first|twenty[ -]+second|twenty[ -]+third|twenty[ -]+fourth|twenty[ -]+fifth|twenty[ -]+sixth|twenty[ -]+seventh|twenty[ -]+eighth|twenty[ -]+ninth|thirtieth|thirty[ -]+first)|एक|दो|तीन|चार|पाँच|छह|सात|आठ|नौ|दस|ग्यारह|बारह|तेरह|चौदह|पंद्रह|सोलह|सत्रह|अठारह|उन्नीस|बीस|इक्कीस|बाईस|तेईस|चौबीस|पच्चीस|छब्बीस|सत्ताईस|अट्ठाईस|उनतीस|तीस|इकतीस)[ ./-]*(?:of +)?(?:(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)|जनवरी|फ़रवरी|फरवरी|मार्च|अप्रैल|मई|जून|जुलाई|अगस्त|सितंबर|सितम्बर|अक्टूबर|अक्तूबर|नवंबर|नवम्बर|दिसंबर|दिसम्बर)|(?:(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)|जनवरी|फ़रवरी|फरवरी|मार्च|अप्रैल|मई|जून|जुलाई|अगस्त|सितंबर|सितम्बर|अक्टूबर|अक्तूबर|नवंबर|नवम्बर|दिसंबर|दिसम्बर)[ ./-]*(?:the +)?(?:(?:[0-9]{1,2}(?:st|nd|rd|th)?|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth|twenty[ -]+first|twenty[ -]+second|twenty[ -]+third|twenty[ -]+fourth|twenty[ -]+fifth|twenty[ -]+sixth|twenty[ -]+seventh|twenty[ -]+eighth|twenty[ -]+ninth|thirtieth|thirty[ -]+first)|एक|दो|तीन|चार|पाँच|छह|सात|आठ|नौ|दस|ग्यारह|बारह|तेरह|चौदह|पंद्रह|सोलह|सत्रह|अठारह|उन्नीस|बीस|इक्कीस|बाईस|तेईस|चौबीस|पच्चीस|छब्बीस|सत्ताईस|अट्ठाईस|उनतीस|तीस|इकतीस))[ ./-]*,[ ./-]*([''’ʼ]?[0-9]{4}|[''’ʼ]?[0-9]{2})(?![0-9])',E'\\1 \\2','g');
 -- One regex cursor owns all head spans; repeated suffix searches would
 -- recompile the large grammar between every projected frame.
 for head_span in select * from app.private_invoice_language_heads(prepared,false) loop
  starts:=array_append(starts,head_span.first_at);
