revoke all on function app.private_invoice_scoped_fact_aliases(uuid,text) from public,anon,authenticated,service_role;

-- Semantic revision covers shared JS/Unicode/SQL and field-role capture rules.
create function app.private_invoice_canonical_revision() returns text
language sql immutable set search_path='' as $$select '6c865d1e92ccc3e6101105d822f774c317eba6d16c51412b60d1ed8a786619c2'::text$$;
revoke all on function app.private_invoice_canonical_revision() from public,anon,authenticated,service_role;

-- The completion key also includes privileged maintenance generations. Read
-- once at entry, before alias work: a later invalidation cannot bless old work.
create function app.private_invoice_capture_revision(p_workspace_id uuid) returns bytea
language sql stable set search_path='' as $$
 select sha256(convert_to(app.private_invoice_canonical_revision()||':'||
  (select generation::text from app.private_invoice_capture_state where singleton)||':'||
  coalesce((select generation::text from app.private_invoice_capture_epochs where workspace_id=p_workspace_id),'0'),'UTF8'));
$$;
revoke all on function app.private_invoice_capture_revision(uuid) from public,anon,authenticated,service_role;

-- Capture each distinct raw field/role once per canonicalizer revision. The
-- completion marker is written last in this transaction, never before aliases.
create function app.retain_private_invoice_field(p_workspace_id uuid,p_value text,p_kind text) returns void
language plpgsql set search_path='' as $$
declare revision bytea; fingerprint bytea; monetary boolean:=false;
begin
 if p_value is null or p_workspace_id is null then return;end if;
 -- Uniform lock order: terms -> generation/cache -> alias/marker writes.
 lock table public.whatsapp_private_invoice_terms in row exclusive mode;
 -- During ON DELETE CASCADE the workspace is already absent. Retention must
 -- not resurrect its private state or prevent the owner's atomic deletion.
 if not exists(select 1 from public.workspaces where id=p_workspace_id) then return;end if;
 revision:=app.private_invoice_capture_revision(p_workspace_id);
 fingerprint:=sha256(convert_to(p_value,'UTF8'));
 if exists(select 1 from app.private_invoice_canonical_inputs c where c.workspace_id=p_workspace_id and c.canonicalizer_revision=revision and c.input_kind=p_kind and c.input_hash=fingerprint) then return;end if;
 if p_kind not in ('generic','monetary','party','number','evidence') then raise exception 'INVALID_PRIVATE_INPUT_KIND';end if;
 if p_kind='monetary' then monetary:=exists(select 1 from app.private_invoice_number_aliases(p_value)) or exists(select 1 from app.private_invoice_word_number_aliases(p_value)) or exists(select 1 from app.private_invoice_evidence_aliases(p_value) k where k ~ '^number(-run)?:');end if;
 insert into public.whatsapp_private_invoice_terms(workspace_id,term_hash,term)
 select distinct p_workspace_id,encode(sha256(convert_to(term,'UTF8')),'hex'),term from (
  select k term from app.private_invoice_term_aliases(p_value) k where p_kind='generic' or p_kind='monetary' and not monetary
  union all select app.private_invoice_normalize(p_value) where monetary and not exists(select 1 from app.private_invoice_term_aliases(p_value) k where k like 'date:%')
  union all select k from app.private_invoice_numeric_candidates(p_value,false) k where monetary or p_kind='number'
  union all select k from app.private_invoice_word_number_aliases(p_value) k where monetary
  union all select k from app.private_invoice_evidence_aliases(p_value) k where monetary and k ~ '^number(-run)?:'
  union all select k from app.private_invoice_term_aliases(p_value) k where p_kind='party' and not exists(select 1 from app.private_invoice_party_aliases(p_value) a where a='party-ref:'||app.private_invoice_normalize(p_value))
  union all select k from app.private_invoice_party_aliases(p_value) k where p_kind='party'
  union all select k from app.private_invoice_evidence_aliases(p_value) k where p_kind='evidence'
 ) aliases where length(term) between 1 and 4000 and exists(select 1 from public.workspaces w where w.id=p_workspace_id) on conflict do nothing;
 -- Explicitly revisit origins even if their raw term predated this revision:
 -- ON CONFLICT alone would not fire the term-insert provenance trigger again.
 if p_kind in ('generic','monetary') then perform app.retain_private_origin_terms(p_workspace_id,p_value);end if;
 insert into app.private_invoice_canonical_inputs values(p_workspace_id,revision,p_kind,fingerprint) on conflict do nothing;
end $$;
revoke all on function app.retain_private_invoice_field(uuid,text,text) from public,anon,authenticated,service_role;

-- Public schema vocabulary has a categorical role. Do not turn enum symbols
-- into unscoped chat identifiers. Project only known record/state paths; an
-- identically spelled invoice number, note or custom field is still private.
create function app.private_invoice_record_facts(p_document jsonb) returns jsonb
language plpgsql immutable set search_path='' as $$
declare facts jsonb:=p_document;entry record;
 -- Catalogs are pinned to invoice_status, core follow-up state and accounting
 -- sync constraints. Unknown/free-form state text remains a private fact.
 catalog constant jsonb:='{"status":["draft","sent","overdue","paid","void","cancelled"],"followup_state":["draft","approved","active","scheduled","paused","cancelled"],"sync_status":["local","pending","synced","failed"],"bookkeeping_sync_status":["not_configured","pending","synced","failed"]}'::jsonb;
begin
 if jsonb_typeof(facts)<>'object' then return facts;end if;
 for entry in select * from jsonb_each(catalog) loop
  if jsonb_typeof(facts->entry.key)='string' and entry.value ? (facts->>entry.key) then facts:=facts-entry.key;end if;
  if jsonb_typeof(facts->'metadata'->entry.key)='string' and entry.value ? (facts->'metadata'->>entry.key) then facts:=facts #- array['metadata',entry.key];end if;
 end loop;
 if jsonb_typeof(facts->'invoice')='object' then
  facts:=jsonb_set(facts,'{invoice}',app.private_invoice_record_facts(facts->'invoice'));
 end if;
 return facts;
end $$;
revoke all on function app.private_invoice_record_facts(jsonb) from public,anon,authenticated,service_role;

-- A path-aware projection preserves semantic roles through arrays and wrapped
-- evidence. A party singleton must never also be captured as a generic string.
create function app.private_invoice_typed_fields(p_document jsonb) returns table(value text,kind text)
language sql immutable set search_path='' as $$
 with recursive fields(document,field_kind,evidence,freeform) as (
  select p_document,'generic'::text,false,false
  union all
  select child.value,
   case when fields.freeform or child.key ~* '^custom[_ ]?fields$' then 'generic'
    when child.key is null then fields.field_kind
    when child.key='value' and fields.field_kind in ('party','monetary') then fields.field_kind
    when child.key ~* '^(?:(?:customer|client|party|company|supplier|vendor|debtor|creditor)(?:[_ -]?names?)?|name|partyNames)$' then 'party'
    when child.key ~* '^(total|subtotal|tax|amount|balance|price|rate|quantity)([_ -]?(amount|paid|due|minor))?$' then 'monetary'
    else 'generic' end,
   fields.evidence or lower(child.key)='printedevidence',
   fields.freeform or child.key ~* '^custom[_ ]?fields$'
  from fields cross join lateral (
   select e.key,e.value from jsonb_each(case when jsonb_typeof(fields.document)='object' then fields.document else '{}'::jsonb end) e
   union all
   select null::text,e.value from jsonb_array_elements(case when jsonb_typeof(fields.document)='array' then fields.document else '[]'::jsonb end) e
  ) child
 )
 select distinct document #>> '{}',case when jsonb_typeof(document)='number' then 'number' else field_kind end
 from fields where jsonb_typeof(document) in ('string','number')
 union
 select distinct document #>> '{}','evidence' from fields where evidence and field_kind not in ('party','monetary') and jsonb_typeof(document)='string';
$$;
revoke all on function app.private_invoice_typed_fields(jsonb) from public,anon,authenticated,service_role;

create function app.retain_private_invoice_terms(p_workspace_id uuid,p_document jsonb) returns void
language plpgsql set search_path='' as $$
declare field record;revision bytea;
begin
 if p_workspace_id is null then return;end if;
 lock table public.whatsapp_private_invoice_terms in row exclusive mode;
 if not exists(select 1 from public.workspaces where id=p_workspace_id) then return;end if;
 revision:=app.private_invoice_capture_revision(p_workspace_id);
 for field in
  with candidates as materialized (
  select * from app.private_invoice_typed_fields(app.private_invoice_record_facts(p_document))
  union select v #>> '{}','party' from jsonb_path_query(p_document,'$.**.partyNames.** ? (@.type() == "string")') v
  union select leaf.value #>> '{}','party' from jsonb_path_query(p_document,'$.** ? (@.type() == "object")') obj
   cross join lateral jsonb_each(obj) f(key,value)
   cross join lateral (select case jsonb_typeof(f.value) when 'string' then f.value when 'object' then f.value->'value' end value) leaf
   where jsonb_typeof(leaf.value)='string' and app.private_invoice_normalize(f.key) ~ '^(?:(?:customer|client|party|company|supplier|vendor|debtor|creditor)(?:[_ -]?names?)?|name)$'
  )
  select candidates.* from candidates where not exists(
   select 1 from app.private_invoice_canonical_inputs completed where completed.workspace_id=p_workspace_id
    and completed.canonicalizer_revision=revision and completed.input_kind=candidates.kind
    and completed.input_hash=sha256(convert_to(candidates.value,'UTF8')))
  -- Resolve record identity before any dependent free-text facts.
  order by case candidates.kind when 'party' then 0 else 1 end,candidates.value
 loop
  perform app.retain_private_invoice_field(p_workspace_id,field.value,field.kind);
 end loop;
end $$;
revoke all on function app.retain_private_invoice_terms(uuid,jsonb) from public,anon,authenticated,service_role;

-- Scoped identity witnesses must not scan the growing numeric/value ledger.
-- Index the role and workspace without indexing potentially long name text.
create index whatsapp_private_invoice_identity_workspace on public.whatsapp_private_invoice_terms(workspace_id) where term ~ '^party(-native|-ref)?:';

create function app.retain_private_origin_terms(p_workspace_id uuid,p_text text) returns void
language plpgsql set search_path='' as $$
declare document jsonb;documents jsonb[];revision bytea;fingerprint bytea;captured boolean:=false;fact text;
begin
 if p_text is null or p_workspace_id is null then return;end if;
 -- Uniform lock order: terms -> generation/cache -> alias/marker writes.
 lock table public.whatsapp_private_invoice_terms in row exclusive mode;
 -- During ON DELETE CASCADE the workspace is already absent. Retention must
 -- not resurrect its private state or prevent the owner's atomic deletion.
 if not exists(select 1 from public.workspaces where id=p_workspace_id) then return;end if;
 -- Only actual origins need database completion state. Scope is checked
 -- first so parent deletion cannot be blocked by decoding a removed source.
 -- Completed entries are already a proof of full projection in this exact
 -- workspace/generation/revision. Check them before decoding the source again.
 revision:=app.private_invoice_capture_revision(p_workspace_id);
 fingerprint:=sha256(convert_to(p_text,'UTF8'));
 if exists(select 1 from app.private_invoice_canonical_inputs c where c.workspace_id=p_workspace_id and c.canonicalizer_revision=revision and c.input_kind='origin' and c.input_hash=fingerprint) then return;end if;
 documents:=array(select distinct * from app.private_invoice_origin_documents(to_jsonb(p_text),0));
 if cardinality(documents)=0 then
  for fact in select distinct * from app.private_invoice_scoped_fact_aliases(p_workspace_id,p_text) loop
   insert into public.whatsapp_private_invoice_terms(workspace_id,term_hash,term) values(p_workspace_id,encode(sha256(convert_to(fact,'UTF8')),'hex'),fact) on conflict do nothing;captured:=true;
  end loop;
  if not captured then return;end if;
 end if;
 foreach document in array documents loop
  captured:=true;
  if jsonb_typeof(document) in ('object','array') then
   perform app.retain_private_invoice_terms(p_workspace_id,document);
  else
   insert into public.whatsapp_private_invoice_terms(workspace_id,term_hash,term)
   select distinct p_workspace_id,encode(sha256(convert_to(term,'UTF8')),'hex'),term
   from app.private_invoice_origin_aliases(document #>> '{}') term where length(term) between 1 and 4000
   and exists(select 1 from public.workspaces w where w.id=p_workspace_id) on conflict do nothing;
  end if;
 end loop;
 if captured then insert into app.private_invoice_canonical_inputs values(p_workspace_id,revision,'origin',fingerprint) on conflict do nothing;end if;
end $$;
revoke all on function app.retain_private_origin_terms(uuid,text) from public,anon,authenticated,service_role;

-- Close provenance at the terms write boundary too. A quoted document stored
-- as a JSON/string field cannot bypass decomposition through a different sink.
create function app.retain_private_term_origin() returns trigger
language plpgsql security definer set search_path='' as $$
declare source text;
begin
 if new.term ~ '^(number|date|identifier|party|party-native|party-latin|party-ref|party-inferred):' or new.term ~ '^number-run:[0-9][0-9.,'' ]*([kmb])?$' or new.term ~ '^number-run:\["[a-f0-9]{64}", [0-9]+, [0-9]+, "[0-9.,'' kmb]+"\]$' then return new;end if;
 source:=regexp_replace(new.term,'^(origin|evidence):','');
 perform app.retain_private_origin_terms(new.workspace_id,source);return new;
end $$;
revoke all on function app.retain_private_term_origin() from public,anon,authenticated,service_role;
create trigger retain_private_term_origin after insert on public.whatsapp_private_invoice_terms
 for each row execute function app.retain_private_term_origin();

create function public.whatsapp_retain_private_chat_origin(p_workspace_id uuid,p_text text) returns boolean
language plpgsql security definer set search_path='' as $$
begin
 if p_workspace_id is null or p_text is null or length(p_text) not between 1 and 4000 then raise exception 'INVALID_PRIVATE_ORIGIN';end if;
 perform app.retain_private_origin_terms(p_workspace_id,p_text);return true;
end $$;
revoke all on function public.whatsapp_retain_private_chat_origin(uuid,text) from public,anon,authenticated;
grant execute on function public.whatsapp_retain_private_chat_origin(uuid,text) to service_role;

create function app.retain_private_review_terms() returns trigger
language plpgsql security definer set search_path='' as $$
declare value jsonb;
begin
 if tg_op<>'INSERT' and old.action->>'type'='invoice_review_draft' then
  value:=old.action;
  perform app.retain_private_invoice_terms(old.workspace_id,jsonb_build_object('invoice',value->'invoice','printedEvidence',value->'printedEvidence','ownerProvidedFacts',value->'ownerProvidedFacts'));
 end if;
 if tg_op<>'DELETE' and new.action->>'type'='invoice_review_draft' then
  value:=new.action;
  perform app.retain_private_invoice_terms(new.workspace_id,jsonb_build_object('invoice',value->'invoice','printedEvidence',value->'printedEvidence','ownerProvidedFacts',value->'ownerProvidedFacts'));
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $$;
revoke all on function app.retain_private_review_terms() from public,anon,authenticated,service_role;
create trigger retain_private_review_terms after insert or update of action or delete on public.whatsapp_pending_actions
 for each row execute function app.retain_private_review_terms();

create function app.retain_private_ledger_document(p_document jsonb) returns void
language sql set search_path='' as $$
 select app.retain_private_invoice_terms((p_document->>'workspace_id')::uuid,p_document||jsonb_build_object('partyNames',(select jsonb_build_array(c.name,c.company_name) from public.customers c where c.workspace_id=(p_document->>'workspace_id')::uuid and c.id=(p_document->>'customer_id')::uuid),'linked_customer',
  (select jsonb_build_object('name',c.name,'company_name',c.company_name,'email',c.email,'phone',c.phone) from public.customers c
   where c.workspace_id=(p_document->>'workspace_id')::uuid and c.id=(p_document->>'customer_id')::uuid)));
$$;
revoke all on function app.retain_private_ledger_document(jsonb) from public,anon,authenticated,service_role;
create function app.retain_private_ledger_terms() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if tg_op='UPDATE' and to_jsonb(old)=to_jsonb(new) then return new;end if;
 if tg_op<>'INSERT' then perform app.retain_private_ledger_document(to_jsonb(old));end if;
 if tg_op<>'DELETE' then perform app.retain_private_ledger_document(to_jsonb(new));end if;
 if tg_op='DELETE' then return old;end if;return new;
end $$;
revoke all on function app.retain_private_ledger_terms() from public,anon,authenticated,service_role;
create trigger retain_private_ledger_terms after insert or update or delete on public.invoices
 for each row execute function app.retain_private_ledger_terms();

create function app.retain_private_invoice_customer_terms() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if exists(select 1 from public.invoices i where i.workspace_id=old.workspace_id and i.customer_id=old.id) then
  perform app.retain_private_invoice_terms(old.workspace_id,jsonb_build_object('partyNames',jsonb_build_array(old.name,old.company_name),'contacts',jsonb_build_array(old.email,old.phone)));
  if tg_op<>'DELETE' then perform app.retain_private_invoice_terms(new.workspace_id,jsonb_build_object('partyNames',jsonb_build_array(new.name,new.company_name),'contacts',jsonb_build_array(new.email,new.phone)));end if;
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $$;
revoke all on function app.retain_private_invoice_customer_terms() from public,anon,authenticated,service_role;
create trigger retain_private_invoice_customer_terms before update of name,company_name,email,phone or delete on public.customers
 for each row execute function app.retain_private_invoice_customer_terms();

create function app.retain_private_chat_origin_terms() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if tg_op<>'INSERT' then perform app.retain_private_origin_terms(old.workspace_id,old.content);end if;
 if tg_op<>'DELETE' then perform app.retain_private_origin_terms(new.workspace_id,new.content);end if;
